<!-- Generated by v0 by Vercel -->
<script setup>
import { ChevronRight, GraduationCap, Sparkles } from 'lucide-vue-next'
import { useAppState } from '../composables/useAppState'
import { computed, ref } from 'vue'

const { authError, loginRole, signIn, signUp, smuSchools, validPhone, phoneHint, toast } = useAppState()
const email = ref('')
const password = ref('')

// Only students can sign up; admin accounts are created by an administrator.
const mode = ref('login')
const busy = ref(false)
const signup = ref({ name: '', email: '', password: '', school: '', programme: '', yearOfStudy: '', contactNumber: '' })
const showPhoneError = computed(() => signup.value.contactNumber.trim() !== '' && !validPhone(signup.value.contactNumber))

function switchMode(next) {
  mode.value = next
  authError.value = ''
  if (next === 'signup') loginRole.value = 'student'
}

// The first problem with the form, in the order the fields appear, or '' when it can be sent.
function signupProblem() {
  const form = signup.value
  if (!form.name.trim()) return 'Enter your name.'
  if (!form.email.trim()) return 'Enter your email.'
  if (!/^\S+@\S+\.\S+$/.test(form.email.trim())) return 'Enter a valid email address.'
  if (form.password.length < 8) return 'Your password needs at least 8 characters.'
  if (!form.school) return 'Choose your school.'
  if (!form.programme.trim()) return 'Enter your programme.'
  if (!form.yearOfStudy) return 'Choose your year of study.'
  if (!form.contactNumber.trim()) return 'Enter your contact number.'
  if (!validPhone(form.contactNumber)) return `Contact number: ${phoneHint}.`
  return ''
}

async function submitSignup() {
  const problem = signupProblem()
  if (problem) { authError.value = problem; toast(problem, 'error'); return }
  const form = signup.value
  busy.value = true
  await signUp({ name: form.name.trim(), email: form.email.trim(), password: form.password, school: form.school,
    programme: form.programme.trim(), yearOfStudy: Number(form.yearOfStudy), contactNumber: form.contactNumber.trim() })
  busy.value = false
}

async function submitLogin() {
  busy.value = true
  await signIn(email.value, password.value)
  busy.value = false
}
</script>

<template>
<div class="auth-shell">
  <div class="auth-brand"><span class="brand-mark"><Sparkles :size="17"/></span>study<span class="brand-accent">buds</span></div>
  <div class="auth-card">
    <div class="auth-icon"><GraduationCap :size="22"/></div>
    <template v-if="mode === 'login'">
      <p class="eyebrow">WELCOME BACK</p>
      <h1>Find your study people.</h1>
      <div class="role-toggle">
        <button :class="{selected:loginRole==='student'}" @click="loginRole='student'">Student</button>
        <button :class="{selected:loginRole==='admin'}" @click="loginRole='admin'">Admin</button>
      </div>
      <form class="auth-form" @submit.prevent="submitLogin">
        <label class="field"><span>Email</span><input v-model="email" type="email" autocomplete="username" placeholder="student@smu.edu.sg" required/></label>
        <label class="field"><span>Password</span><input v-model="password" type="password" autocomplete="current-password" required/></label>
        <p v-if="authError" class="auth-error" role="alert">{{authError}}</p>
        <button class="primary-button auth-submit" type="submit" :disabled="busy">Log in <ChevronRight :size="16"/></button>
      </form>
      <button v-if="loginRole === 'student'" class="auth-switch" @click="switchMode('signup')">New to StudyBuds? Create a student account</button>
    </template>
    <template v-else>
      <p class="eyebrow">NEW TO STUDYBUDS</p>
      <h1>Create your student account.</h1>
      <p class="auth-subtitle">All fields are required. You can add courses, goals and availability from your profile afterwards.</p>
      <form class="auth-form auth-signup" novalidate @submit.prevent="submitSignup">
        <label class="field"><span>Name</span><input v-model="signup.name" autocomplete="name" placeholder="Alex Tan" required/></label>
        <label class="field"><span>Email</span><input v-model="signup.email" type="email" autocomplete="email" placeholder="student@smu.edu.sg" required/></label>
        <label class="field"><span>Password</span><input v-model="signup.password" type="password" autocomplete="new-password" minlength="8" required/><em class="field-hint">At least 8 characters.</em></label>
        <label class="field"><span>School</span><select v-model="signup.school" required>
          <option value="" disabled>Choose your school</option>
          <option v-for="school in smuSchools" :key="school">{{ school }}</option>
        </select></label>
        <div class="auth-row">
          <label class="field"><span>Programme</span><input v-model="signup.programme" placeholder="Information Systems" required/></label>
          <label class="field"><span>Year of study</span><select v-model="signup.yearOfStudy" required>
            <option value="" disabled>Choose year</option>
            <option v-for="year in 5" :key="year" :value="year">Year {{ year }}</option>
          </select></label>
        </div>
        <label class="field"><span>Contact number</span><input v-model="signup.contactNumber" type="tel" autocomplete="tel" placeholder="+65 8123 4567"
          :aria-invalid="showPhoneError" required/><em v-if="showPhoneError" class="field-hint field-error">{{ phoneHint }}</em><em v-else
          class="field-hint">Start with your country code, e.g. +65 for Singapore. Hidden until you accept a connection.</em></label>
        <p v-if="authError" class="auth-error" role="alert">{{authError}}</p>
        <button class="primary-button auth-submit" type="submit" :disabled="busy">Create account <ChevronRight :size="16"/></button>
      </form>
      <button class="auth-switch" @click="switchMode('login')">Already have an account? Log in</button>
    </template>
  </div>
</div>
</template>
